// ─── Animations ───────────────────────────────────────────────────────────────

const fadeUp = keyframes`
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
`;

const subtleFloat = keyframes`
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-3px); }
`;

const shimmerSweep = keyframes`
  0% { transform: translateX(-100%) skewX(-15deg); }
  100% { transform: translateX(200%) skewX(-15deg); }
`;

const iconFloat = keyframes`
  0%, 100% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-3px) scale(1.05); }
`;

const auroraDrift = keyframes`
  0%   { top: -22vmax; right: -22vmax; }
  20%  { top: 10%;    right: 30%; }
  40%  { top: 50%;    right: 60%; }
  60%  { top: 70%;    right: 20%; }
  80%  { top: 20%;    right: 70%; }
  100% { top: -22vmax; right: -22vmax; }
`;

const auroraDrift2 = keyframes`
  0%   { bottom: -20vmax; left: -20vmax; }
  25%  { bottom: 30%;    left: 40%; }
  50%  { bottom: 60%;    left: 70%; }
  75%  { bottom: 10%;    left: 50%; }
  100% { bottom: -20vmax; left: -20vmax; }
`;

/* ~60-80s per full loop — barely perceptible movement */

